const telegramData = $('Kiểm Tra Loại Message').item.json;
const userMessage = (telegramData.message.text || '').trim();
const chatId = telegramData.message.chat.id;
const userName = telegramData.message.from.first_name || 'Bạn';

// Đọc từ 2 HTTP Request nodes (products + faqs)
const allItems = $input.all();
const products = [];
const faqs = [];

for (const item of allItems) {
 const resp = item.json;
 // Unwrap API response: { success: true, data: [...] }
 const dataArr = resp.data || resp;
 const rows = Array.isArray(dataArr) ? dataArr : [dataArr];

 for (const row of rows) {
   // Product fields (camelCase from API)
   if (row.id && row.name && row.price !== undefined) {
     products.push({
       id: String(row.id || ''),
       name: (row.name || '').toLowerCase(),
       name_orig: row.name || '',
       brand: (row.brand || '').toLowerCase(),
       brand_orig: row.brand || '',
       sport: row.sport || '',
       category: row.category || '',
       price: Number(row.price || 0),
       description: row.description || '',
       stock: row.stockStatus || 'Không rõ',
     });
   }
   // FAQ fields
   if (row.topic && row.answer) {
     faqs.push({
       topic: row.topic || '',
       keywords: (row.questionKeywords || '').toLowerCase(),
       answer: row.answer || '',
     });
   }
 }
}

// —— INTENT DETECTION ——
const msg = userMessage.toLowerCase();

const INTENT_MAP = [
 ['exchange', ['đổi hàng', 'trả hàng', 'hoàn tiền', 'đổi size', 'đổi trả', 'đổi', 'trả', 'hoàn']],
 ['shipping', ['phí ship', 'giao hàng', 'vận chuyển', 'thời gian giao', 'ship']],
 ['payment', ['thanh toán', 'trả tiền', 'cod', 'chuyển khoản', 'momo', 'zalopay', 'zalo']],
 ['warranty', ['bảo hành', 'hàng lỗi', 'lỗi hàng', 'bảo hành mấy tháng']],
 ['stock', ['còn hàng', 'còn không', 'hết hàng', 'có hàng', 'tồn kho', 'stock']],
 ['compare', ['so sánh', 'khác nhau', 'tốt hơn', 'nên chọn', 'hay là']],
 ['describe', ['mô tả', 'giới thiệu', 'thông tin', 'chi tiết', 'công nghệ', 'như thế nào', 'ra sao']],
 ['brand', ['hãng nào', 'thương hiệu', 'brand', 'của ai', 'sản xuất', 'nhà sản xuất']],
 ['size', ['bảng size', 'size áo', 'size giày', 'cỡ áo', 'cỡ giày', 'số giày', 'size']],
 ['price', ['giá bao nhiêu', 'bao nhiêu tiền', 'giá', 'bao nhiêu', 'tiền', 'price', 'cost']],
];

let intent = 'general';
for (const [key, kws] of INTENT_MAP) {
 if (kws.some(k => msg.includes(k))) { intent = key; break; }
}

const POLICY_INTENTS = ['exchange','size','shipping','payment','warranty'];
const isPolicy = POLICY_INTENTS.includes(intent);

// —— SMART PRODUCT FILTER ——
const STOP = new Set(['của','và','có','không','cho','bao','nhiêu','giá','còn','thì','sao','muốn','mua','cái','chiếc','đôi','như','nào','rồi','này','đó']);
const tokens = msg.replace(/[?,!.]/g,'').split(/\s+/).filter(t => t.length > 1 && !STOP.has(t));

function scoreProduct(p) {
 let score = 0;
 for (const tok of tokens) {
   if (p.name.includes(tok)) score += 10;
   if (p.brand.includes(tok)) score += 8;
   if (p.category.toLowerCase().includes(tok)) score += 5;
   if (p.sport.toLowerCase().includes(tok)) score += 4;
   if (p.description.toLowerCase().includes(tok)) score += 2;
 }
 return score;
}

function scoreFaq(f) {
 let score = 0;
 for (const tok of tokens) {
   if (f.keywords.includes(tok)) score += 10;
   if (f.topic.toLowerCase().includes(tok)) score += 5;
   if (f.answer.toLowerCase().includes(tok)) score += 2;
 }
 return score;
}

let filteredProducts = [];
if (!isPolicy) {
 filteredProducts = products
   .map(p => ({ ...p, score: scoreProduct(p) }))
   .filter(p => p.score > 0)
   .sort((a, b) => b.score - a.score)
   .slice(0, 3);
 if (filteredProducts.length === 0 && intent === 'general') {
   filteredProducts = products.slice(0, 3);
 }
}

let filteredFaqs = [];
if (isPolicy || intent === 'general') {
 filteredFaqs = faqs
   .map(f => ({ ...f, score: scoreFaq(f) }))
   .filter(f => f.score > 0)
   .sort((a, b) => b.score - a.score)
   .slice(0, 3);
 if (filteredFaqs.length === 0 && isPolicy) filteredFaqs = faqs.slice(0, 3);
}

if (intent === 'compare') {
 filteredProducts = products
   .map(p => ({ ...p, score: scoreProduct(p) }))
   .filter(p => p.score > 0)
   .sort((a, b) => b.score - a.score)
   .slice(0, 4);
 if (filteredProducts.length === 0) filteredProducts = products.slice(0, 4);
}

function sanitize(str) {
 return String(str)
   .replace(/[\r\n\t]/g, ' ')
   .replace(/[\x00-\x1F\x7F]/g, ' ')
   .trim();
}

let productContext = '';
for (const p of filteredProducts) {
 productContext += `- [${p.id}] ${p.name_orig} | Hãng: ${p.brand_orig} | Loại: ${p.category} | Môn: ${p.sport} | Giá: ${p.price.toLocaleString('vi-VN')} VNĐ | Tình trạng: ${p.stock} | Mô tả: ${p.description}\n`;
}

let faqContext = '';
for (const f of filteredFaqs) {
 faqContext += `- [${f.topic}] ${f.answer}\n`;
}

return [{
 json: {
   chatId,
   userName: sanitize(userName),
   userMessage: sanitize(userMessage),
   intent,
   isPolicy,
   productContext: sanitize(productContext) || 'Không tìm thấy sản phẩm phù hợp',
   faqContext: sanitize(faqContext) || 'Không có FAQ phù hợp',
   filteredCount: filteredProducts.length,
   timestamp: new Date().toISOString(),
 }
}];

const ctx = $('Smart Filter + Intent').item.json;

// Đọc memory
let conversationHistory = [];
try {
 const memItems = $input.all();
 if (memItems.length > 0 && memItems[0].json.history_json) {
 conversationHistory = JSON.parse(memItems[0].json.history_json);
 }
} catch(e) {
 conversationHistory = [];
}
conversationHistory = conversationHistory.slice(-5);

// Build history string
let historyStr = '';
if (conversationHistory.length > 0) {
 historyStr = '[LỊCH SỬ HỘI THOẠI]\n';
 for (const turn of conversationHistory) {
 historyStr += `Khách: ${turn.user}\nTư vấn viên: ${turn.bot}\n`;
 }
 historyStr += '\n';
}

// Build data block
let dataBlock = '';
let hasProduct = ctx.productContext !== 'Không tìm thấy sản phẩm phù hợp';
let hasFaq = ctx.faqContext !== 'Không có FAQ phù hợp';

if (hasProduct) dataBlock += `[SẢN PHẨM]\n${ctx.productContext}\n`;
if (hasFaq) dataBlock += `[CHÍNH SÁCH]\n${ctx.faqContext}\n`;

// Intent guidance
const intentGuide = {
 stock: 'Thông báo tình trạng tồn kho. Chỉ dùng giá trị cột "Tình trạng" từ [SẢN PHẨM].',
 price: 'Nêu giá sản phẩm. Chỉ dùng số trong cột "Giá" từ [SẢN PHẨM]. Không tự tính toán hay ước lượng.',
 describe: 'Mô tả sản phẩm dựa đúng theo cột "Mô tả" từ [SẢN PHẨM].',
 brand: 'Xác nhận thương hiệu từ cột "Hãng" trong [SẢN PHẨM].',
 exchange: 'Trả lời dựa đúng nội dung [CHÍNH SÁCH] mục đổi trả.',
 size: 'Trả lời dựa đúng nội dung [CHÍNH SÁCH] mục size.',
 shipping: 'Trả lời dựa đúng nội dung [CHÍNH SÁCH] mục vận chuyển.',
 payment: 'Trả lời dựa đúng nội dung [CHÍNH SÁCH] mục thanh toán.',
 warranty: 'Trả lời dựa đúng nội dung [CHÍNH SÁCH] mục bảo hành.',
 compare: 'So sánh các sản phẩm trong [SẢN PHẨM]. Chỉ dùng thông tin có sẵn, không thêm.',
 general: 'Giới thiệu sản phẩm từ [SẢN PHẨM]. Hỏi thêm nhu cầu cụ thể.',
};
const guide = intentGuide[ctx.intent] || intentGuide.general;

// Few-shot examples theo intent
const fewShots = {
 price: `VÍ DỤ ĐÚNG:
[SẢN PHẨM]: - [7] Giày Chạy Bộ Asics Novablast 4 | Hãng: Asics | Loại: Giày chạy bộ | Môn: Chạy bộ | Giá: 3.280.000 VNĐ | Tình trạng: còn hàng | Mô tả: Đệm FlyteFoam
Khách: Asics Novablast giá bao nhiêu?
Tư vấn viên: Giày Asics Novablast 4 có giá 3.280.000 VNĐ và hiện còn hàng ✅ Bạn muốn biết thêm về công nghệ đệm của đôi này không?

VÍ DỤ SAI (KHÔNG ĐƯỢC LÀM):
Khách: Nike Air Zoom Pegasus giá bao nhiêu?
Tư vấn viên SAI: Nike Air Zoom Pegasus giá 3.999.000 VNĐ ← SAI vì sản phẩm này không có trong [SẢN PHẨM]
Tư vấn viên ĐÚNG: Mình chưa có thông tin về Nike Air Zoom Pegasus trong hệ thống. Bạn liên hệ hotline để được hỗ trợ nhé! 📞`,

 stock: `VÍ DỤ ĐÚNG:
[SẢN PHẨM]: - [7] Giày Asics Novablast 4 | Tình trạng: còn hàng
Khách: Asics Novablast còn hàng không?
Tư vấn viên: Giày Asics Novablast 4 hiện còn hàng ✅ Bạn muốn biết thêm giá hoặc thông tin sản phẩm không?

VÍ DỤ SAI (KHÔNG ĐƯỢC LÀM):
Khách: Nike Pegasus còn hàng không?
Tư vấn viên SAI: Nike Pegasus hiện còn hàng ← SAI vì không có trong [SẢN PHẨM]
Tư vấn viên ĐÚNG: Mình chưa tìm thấy Nike Pegasus trong hệ thống. Bạn liên hệ hotline nhé! 📞`,

 shipping: `VÍ DỤ ĐÚNG:
[CHÍNH SÁCH]: - [vận chuyển] Giao hàng toàn quốc 2-5 ngày. Miễn phí ship đơn từ 2.000.000đ.
Khách: Phí ship như nào?
Tư vấn viên: Giao hàng toàn quốc 2-5 ngày. Miễn phí ship cho đơn từ 2.000.000đ 🚚 Bạn đang ở khu vực nào để mình tư vấn thêm?

VÍ DỤ SAI (KHÔNG ĐƯỢC LÀM):
Tư vấn viên SAI: Miễn phí ship đơn từ 500.000đ ← SAI, không đúng với [CHÍNH SÁCH]`,

 size: `VÍ DỤ ĐÚNG:
[CHÍNH SÁCH]: - [bảng size giày] 38=24cm, 39=24.5cm, 40=25cm, 41=25.5cm, 42=26cm, 43=27cm, 44=28cm
Khách: Bàn chân 26cm đi size mấy?
Tư vấn viên: Bàn chân 26cm tương ứng size 42 👟 Nên đo bàn chân vào buổi chiều để chọn size chính xác nhất nhé!`,

 general: `VÍ DỤ ĐÚNG:
Khách: Cho tôi xem sản phẩm
Tư vấn viên: TheXuong có nhiều sản phẩm thể thao chất lượng! 👟 Bạn đang quan tâm đến môn thể thao nào: chạy bộ, bóng đá, cầu lông hay khác?

VÍ DỤ SAI (KHÔNG ĐƯỢC LÀM):
Tư vấn viên SAI: Chúng tôi có Nike Air Max, Adidas Ultraboost... ← SAI nếu không có trong [SẢN PHẨM]`,
};

const shot = fewShots[ctx.intent] || fewShots.general;

const dataStatus = hasProduct || hasFaq
 ? 'Dưới đây là DỮ LIỆU THỰC TẾ từ hệ thống. Đây là nguồn sự thật DUY NHẤT. TUYỆT ĐỐI KHÔNG dùng kiến thức bên ngoài.'
 : 'KHÔNG CÓ DỮ LIỆU PHÙ HỢP. Bắt buộc trả lời: "Mình chưa có thông tin này, bạn liên hệ hotline nhé! 📞"';

const prompt =
`Bạn là tư vấn viên của TheXuong Sport Store.

===LUẬT TUYỆT ĐỐI===
LUẬT 1: Chỉ được dùng thông tin trong [SẢN PHẨM] và [CHÍNH SÁCH] bên dưới. CẤM dùng kiến thức bên ngoài. Nếu thông tin không có trong dữ liệu → trả lời "Mình chưa có thông tin này, bạn liên hệ hotline nhé! 📞"
LUẬT 2: Giá, tên sản phẩm, tình trạng hàng → copy CHÍNH XÁC từ dữ liệu, KHÔNG ước lượng hay làm tròn.
LUẬT 3: Tối đa 100 từ. Không dùng markdown. Emoji phù hợp.
LUẬT 4 (nhiệm vụ): ${guide}

===DỮ LIỆU=== (${dataStatus})
${dataBlock || '(Trống)'}
===FEW-SHOT===
${shot}

${historyStr}Khách (${ctx.userName}): ${ctx.userMessage}
Tư vấn viên:`;

return [{
 json: {
 chatId: ctx.chatId,
 userName: ctx.userName,
 userMessage: ctx.userMessage,
 intent: ctx.intent,
 timestamp: ctx.timestamp,
 conversationHistory: conversationHistory,
 requestBody: {
 model: "qwen3.5:4b",
 prompt: prompt,
 stream: false,
    think: false,
 options: {
 temperature: 0.1,
 top_p: 0.85,
 num_predict: 600,
 repeat_penalty: 1.2,
 }
 },
 }
}];

const ollamaRaw = $json.response || $json.thinking || '';
// Strip <think>...</think> block — never expose to user
const thinkMatch = ollamaRaw.match(/<think>[\s\S]*?<\/think>/i);
const ollamaResp = thinkMatch ? ollamaRaw.replace(thinkMatch[0], '').trim() : ollamaRaw.trim();
const buildCtx = $('Build Prompt').item.json;

const botReply = ollamaResp ||
  'Xin lỗi, hệ thống đang bận. Vui lòng thử lại sau! 🙏';

const history = buildCtx.conversationHistory || [];
history.push({ user: buildCtx.userMessage, bot: ollamaResp });
const updatedHistory = history.slice(-5);

return [{
  json: {
    chatId: buildCtx.chatId,
    userName: buildCtx.userName,
    userMessage: buildCtx.userMessage,
    intent: buildCtx.intent,
    botReply: botReply,
    botReplyRaw: ollamaResp,
    updatedHistory: updatedHistory,
    timestamp: buildCtx.timestamp,
  }
}];

const d = $json;
const historyJson = JSON.stringify(d.updatedHistory);
const now = new Date().toISOString();

return [{
 json: {
 chatId: d.chatId,
 userName: d.userName,
 userMessage: d.userMessage,
 intent: d.intent,
 botReply: d.botReplyRaw,
 timestamp: d.timestamp,
 historyJson: historyJson,
 updatedAt: now,
 }
}];
